   163→func ProcessBlockNoVerifyAnySig(
   164→	ctx context.Context,
   165→	st state.BeaconState,
   166→	signed interfaces.ReadOnlySignedBeaconBlock,
   167→) (*bls.SignatureBatch, state.BeaconState, error) {
   168→	ctx, span := trace.StartSpan(ctx, "core.state.ProcessBlockNoVerifyAnySig")
   169→	defer span.End()
   170→	if err := blocks.BeaconBlockIsNil(signed); err != nil {
   171→		return nil, nil, err
   172→	}
   173→
   174→	if st.Version() != signed.Block().Version() {
   175→		return nil, nil, fmt.Errorf("state and block are different version. %d != %d", st.Version(), signed.Block().Version())
   176→	}
   177→
   178→	blk := signed.Block()
   179→	st, err := ProcessBlockForStateRoot(ctx, st, signed)
   180→	if err != nil {
   181→		return nil, nil, err
   182→	}
   183→
   184→	sig := signed.Signature()
   185→	bSet, err := b.BlockSignatureBatch(st, blk.ProposerIndex(), sig[:], blk.HashTreeRoot)
   186→	if err != nil {
   187→		tracing.AnnotateError(span, err)
   188→		return nil, nil, errors.Wrap(err, "could not retrieve block signature set")
   189→	}
   190→	randaoReveal := signed.Block().Body().RandaoReveal()
   191→	rSet, err := b.RandaoSignatureBatch(ctx, st, randaoReveal[:])
   192→	if err != nil {
   193→		tracing.AnnotateError(span, err)
   194→		return nil, nil, errors.Wrap(err, "could not retrieve randao signature set")
   195→	}
   196→	aSet, err := b.AttestationSignatureBatch(ctx, st, signed.Block().Body().Attestations())
   197→	if err != nil {
   198→		return nil, nil, errors.Wrap(err, "could not retrieve attestation signature set")
   199→	}
   200→
   201→	// Merge beacon block, randao and attestations signatures into a set.
   202→	set := bls.NewSet()
   203→	set.Join(bSet).Join(rSet).Join(aSet)
   204→
   205→	if blk.Version() >= version.Capella {
   206→		changes, err := signed.Block().Body().BLSToExecutionChanges()
   207→		if err != nil {
   208→			return nil, nil, errors.Wrap(err, "could not get BLSToExecutionChanges")
   209→		}
   210→		cSet, err := b.BLSChangesSignatureBatch(st, changes)
   211→		if err != nil {
   212→			return nil, nil, errors.Wrap(err, "could not get BLSToExecutionChanges signatures")
   213→		}
   214→		set.Join(cSet)
   215→	}
   216→	return set, st, nil
